function localizeStudyString(lang,value){const dictionary=studyTranslations[lang];if(dictionary[value])return dictionary[value];const dynamic={en:[[/^Imagen seleccionada: (.+)\. El análisis real necesita conectar un servicio de IA\.$/,'Selected image: $1. Real analysis requires an AI service.'],[/^Repaso de (.+)$/,'Review of $1'],[/^Practica una explicación en voz alta sobre (.+)\.$/,'Practise explaining $1 aloud.'],[/^Elige el nivel para estudiar los materiales de (.+)\.$/,'Choose a level to study the materials for $1.'],[/^✦ Tutor de (.+)$/,'✦ Tutor for $1'],[/^Pregunta sobre (.+?)(?:…|\.\.\.)$/,'Ask about $1…'],[/^Elige una idea de (.+) y explica cómo se la enseñarías a otra persona\.$/,'Choose an idea from $1 and explain how you would teach it to someone else.'],[/^Configura el simulacro de (.+) antes de generar el PDF\.$/,'Set up the mock exam for $1 before generating the PDF.'],[/^(\d+) preguntas · hoja de respuestas · (\d+) materiales en esta asignatura$/,'$1 questions · answer sheet · $2 materials in this subject'],[/^(Básica|Intermedia|Avanzada) · (\d+) minutos?$/,(all,level,time)=>`${({Básica:'Basic',Intermedia:'Intermediate',Avanzada:'Advanced'})[level]} · ${time} ${time==='1'?'minute':'minutes'}`],[/^(\d+) min$/,'$1 minutes'],[/^Estás estudiando (.+)\. Haz una pregunta sobre esta asignatura\.$/,'You are studying $1. Ask a question about this subject.'],[/^¿Puedes explicar con tus palabras una de las ideas principales de (.+)\?$/,'Can you explain one of the main ideas from $1 in your own words?'],[/^¿Qué número sigue\?$/,'What number comes next?']],eu:[[/^Imagen seleccionada: (.+)\. El análisis real necesita conectar un servicio de IA\.$/,'Aukeratutako irudia: $1. Benetako azterketak IA zerbitzu bat behar du.'],[/^Repaso de (.+)$/,'Errepasoa: $1'],[/^Practica una explicación en voz alta sobre (.+)\.$/,'Praktikatu $1 ozen azaltzen.'],[/^Elige el nivel para estudiar los materiales de (.+)\.$/,'Aukeratu maila bat $1 ikasgaiko materialak ikasteko.'],[/^✦ Tutor de (.+)$/,'✦ $1 ikasgaiko tutorea'],[/^Pregunta sobre (.+?)(?:…|\.\.\.)$/,'Galdetu $1 gaiari buruz…'],[/^Elige una idea de (.+) y explica cómo se la enseñarías a otra persona\.$/,'Aukeratu $1 ikasgaiko ideia bat eta azaldu nola irakatsiko zeniokeen beste bati.'],[/^Configura el simulacro de (.+) antes de generar el PDF\.$/,'Konfiguratu $1 ikasgaiko simulazioa PDFa sortu aurretik.'],[/^(\d+) preguntas · hoja de respuestas · (\d+) materiales en esta asignatura$/,'$1 galdera · erantzun-orria · $2 material ikasgai honetan'],[/^(Básica|Intermedia|Avanzada) · (\d+) minutos?$/,(all,level,time)=>`${({Básica:'Oinarrizkoa',Intermedia:'Ertaina',Avanzada:'Aurreratua'})[level]} · ${time} minutu`],[/^(\d+) min$/,'$1 minutu'],[/^Estás estudiando (.+)\. Haz una pregunta sobre esta asignatura\.$/,'$1 ikasten ari zara. Egin galdera bat ikasgai honi buruz.'],[/^¿Puedes explicar con tus palabras una de las ideas principales de (.+)\?$/,'Azaldu dezakezu zure hitzekin $1 ikasgaiko ideia nagusietako bat?'],[/^¿Qué número sigue\?$/,'Zein zenbaki dator hurrena?']]};for(const [pattern,replacement] of dynamic[lang]||[])if(pattern.test(value))return value.replace(pattern,replacement);return value}
function translateStudyModal(course,root=content){const lang=course?.language;if(!['en','eu'].includes(lang)||!root)return;const dictionary=studyTranslations[lang],titlePatterns=lang==='en'?[[/^Simulacro oral · (.+)$/,'Oral mock exam · $1'],[/^Podcast · (.+)$/,'Podcast · $1'],[/^Texto inteligente · (.+)$/,'Smart text · $1'],[/^Ejercicio guiado · (.+)$/,'Guided exercise · $1'],[/^Tutor · (.+)$/,'Tutor · $1'],[/^Repaso de (.+)$/,'Review · $1'],[/^Calendario · (.+)$/,'Calendar · $1'],[/^Verdadero o falso · (.+)$/,'True or false · $1'],[/^Simulacro escrito · (.+)$/,'Written mock exam · $1']]:[[/^Simulacro oral · (.+)$/,'Ahozko simulazioa · $1'],[/^Podcast · (.+)$/,'Podcasta · $1'],[/^Texto inteligente · (.+)$/,'Testu adimenduna · $1'],[/^Ejercicio guiado · (.+)$/,'Ariketa gidatua · $1'],[/^Tutor · (.+)$/,'Tutorea · $1'],[/^Repaso de (.+)$/,'Errepasoa · $1'],[/^Calendario · (.+)$/,'Egutegia · $1'],[/^Verdadero o falso · (.+)$/,'Egia ala gezurra · $1'],[/^Simulacro escrito · (.+)$/,'Idatzizko simulazioa · $1']];const heading=document.querySelector('#modalTitle');if(heading){let value=heading.textContent;for(const [pattern,replacement] of titlePatterns)value=value.replace(pattern,replacement);heading.textContent=localizeStudyString(lang,value)}const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode())){const raw=node.nodeValue,trimmed=raw.trim(),translated=localizeStudyString(lang,trimmed);if(translated!==trimmed)node.nodeValue=raw.replace(trimmed,translated)}root.querySelectorAll('input[placeholder],button[title]').forEach(element=>{for(const attribute of ['placeholder','title'])if(element.hasAttribute(attribute)){const value=element.getAttribute(attribute),translated=localizeStudyString(lang,value);if(translated!==value)element.setAttribute(attribute,translated)}})}
async function cloudRequest(path,options={}){const response=await fetch(`/api/${path}`,{...options,headers:{...(options.body instanceof Blob?{}:{'Content-Type':'application/json'}),...(options.headers||{})}});let result;if(response.headers.get('content-type')?.includes('application/json'))result=await response.json();else result=await response.blob();if(!response.ok)throw new Error(result?.error||'No se pudo conectar con tu cuenta.');return result}
async function persistCloudCourses(courses=loadCourses()){if(!cloudUser)return;await cloudRequest('study-data',{method:'PUT',body:JSON.stringify({courses})})}
function localFile(courseId,sourceId){return new Promise((resolve,reject)=>{const request=indexedDB.open('astra-estudio-local',1);request.onupgradeneeded=()=>request.result.createObjectStore('files',{keyPath:'id'});request.onerror=()=>reject(request.error);request.onsuccess=()=>{const db=request.result,get=db.transaction('files','readonly').objectStore('files').get(`${courseId}:${sourceId}`);get.onsuccess=()=>{db.close();resolve(get.result?.blob||null)};get.onerror=()=>{db.close();reject(get.error)}}})}
async function uploadCloudFile(courseId,source){const blob=source.fileData||await localFile(courseId,source.id);if(!blob)throw new Error(`No se encontró el archivo local «${source.name}».`);const chunkSize=4*1024*1024,total=Math.max(1,Math.ceil(blob.size/chunkSize));for(let chunk=0;chunk<total;chunk++){const part=blob.slice(chunk*chunkSize,Math.min(blob.size,(chunk+1)*chunkSize));await cloudRequest(`study-file?course=${encodeURIComponent(courseId)}&source=${encodeURIComponent(source.id)}&chunk=${chunk}&total=${total}`,{method:'PUT',headers:{'Content-Type':source.mime||blob.type||'application/octet-stream','X-File-Name':encodeURIComponent(source.name),'X-File-Size':String(blob.size)},body:part})}source.cloudStored=true;source.cloudChunks=total}
async function activateCloudUser(user){cloudUser=user;const remote=await cloudRequest('study-data'),local=loadCourses();let courses=remote.courses;if(!courses.length)courses=local;else{const remoteIds=new Set(courses.map(course=>course.id)),localOnly=local.filter(course=>!remoteIds.has(course.id));for(const course of localOnly)for(const source of course.sources||[])if(source.type==='file'&&!source.cloudStored)await uploadCloudFile(course.id,source);courses=[...courses,...localOnly]}if(courses.length&&(!remote.courses.length||courses.length!==remote.courses.length))await cloudRequest('study-data',{method:'PUT',body:JSON.stringify({courses})});localStorage.setItem('astra-demo-courses',JSON.stringify(courses));localStorage.setItem('astra-demo-user',JSON.stringify({email:user.email,name:user.name,id:user.id,cloud:true}));setUser(user.name);renderCourseList()}
async function syncCurrentUser(){try{const {user}=await cloudRequest('me');if(user)await activateCloudUser(user)}catch{}}
function storeLocalFiles(courseId,sources){const files=sources.filter(s=>s.type==='file'&&s.fileData);if(!files.length)return Promise.resolve();return new Promise((resolve,reject)=>{const request=indexedDB.open('astra-estudio-local',1);request.onupgradeneeded=()=>request.result.createObjectStore('files',{keyPath:'id'});request.onerror=()=>reject(request.error);request.onsuccess=()=>{const db=request.result,tx=db.transaction('files','readwrite'),store=tx.objectStore('files');for(const source of files)store.put({id:`${courseId}:${source.id}`,blob:source.fileData});tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{const error=tx.error;db.close();reject(error)}}})}
async function openLocalFile(courseId,sourceId){try{const saved=await localFile(courseId,sourceId);if(saved){const href=URL.createObjectURL(saved),a=document.createElement('a');a.href=href;a.download=saved.name||'material';a.click();setTimeout(()=>URL.revokeObjectURL(href),10000);return}const source=loadCourses().find(c=>c.id===courseId)?.sources.find(s=>s.id===sourceId);if(!cloudUser||!source?.cloudStored)throw new Error('No se encontró este archivo en el almacenamiento local.');const base=`study-file?course=${encodeURIComponent(courseId)}&source=${encodeURIComponent(sourceId)}`;let blob;if(source.cloudChunks){const parts=[];for(let chunk=0;chunk<source.cloudChunks;chunk++)parts.push(await cloudRequest(`${base}&chunk=${chunk}`));blob=new Blob(parts,{type:source.mime||'application/octet-stream'})}else blob=await cloudRequest(base);const href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=source.name||'material';a.click();setTimeout(()=>URL.revokeObjectURL(href),10000)}catch(error){toast(error.message||'No se pudo abrir el archivo.')}}
let sourceMode='create';
function currentCourseCount(){const id=document.querySelector('#courseSelect')?.value;if(sourceMode==='add'&&id)return loadCourses().find(c=>c.id===id)?.sources.length||0;return 0}
function updateSelectedCourseFields(){const course=loadCourses().find(c=>c.id===document.querySelector('#courseSelect')?.value);if(!course)return;document.querySelector('#examDate').value=course.examDate||'';document.querySelector('#courseLanguage').value=course.language||'es';document.querySelector('#targetGrade').value=course.targetGrade||8}
function renderSources(){const list=document.querySelector('#sourceList'),count=document.querySelector('#sourceCount');if(!list||!count)return;const save=document.querySelector('#saveCourseSources');if(save&&sourceMode==='add')save.textContent=pendingSources.length?'Añadir al curso':'Guardar cambios';count.textContent=`${currentCourseCount()+pendingSources.length}/50 materiales`;list.innerHTML=pendingSources.map((s,i)=>`<div class="source-row"><span>${s.type==='youtube'?'▶':s.type==='link'?'↗':'▤'}</span><span class="source-name" title="${escapeHtml(s.name)}">${escapeHtml(s.name)}</span><button class="source-remove" data-remove-source="${i}" aria-label="Quitar ${escapeHtml(s.name)}">×</button></div>`).join('')||'<div class="source-empty">Aún no has añadido materiales.</div>'}
function addSource(source){if(currentCourseCount()+pendingSources.length>=50){toast('Has alcanzado el máximo de 50 materiales para este curso.');return false}if(source.type==='file'&&!source.id)source.id=crypto.randomUUID?.()||`${Date.now()}-${Math.random()}`;pendingSources.push(source);renderSources();return true}
function openMaterialDialog(mode='create',courseId=''){pendingSources=[];sourceMode=mode;const courses=loadCourses();const selected=courses.find(c=>c.id===courseId)||courses[0];const courseField=mode==='create'?`<label class="auth-label">Nombre del curso<input class="field" id="courseName" placeholder="Ej. Biología celular" required></label>`:`<label class="auth-label">Añadir materiales a<select class="field" id="courseSelect">${courses.map(c=>`<option value="${escapeHtml(c.id)}" ${c.id===selected?.id?'selected':''}>${escapeHtml(c.name)} · ${c.sources.length}/50</option>`).join('')}</select></label><button class="text-action" id="createAnotherCourse" type="button">＋ Crear un curso distinto</button>`;const languageField=`<label class="auth-label">Idioma de las respuestas<select class="field" id="courseLanguage"><option value="es" ${(selected?.language||'es')==='es'?'selected':''}>Castellano</option><option value="eu" ${(selected?.language||'es')==='eu'?'selected':''}>Euskera</option><option value="en" ${(selected?.language||'es')==='en'?'selected':''}>English</option></select><small>Las actividades y respuestas de esta asignatura usarán este idioma.</small></label>`;openModal(mode==='create'?'Crear un curso':'Añadir materiales',`<p>${mode==='create'?'Crea un curso independiente con sus propios materiales y fecha de examen.':'Elige el curso al que pertenecen estos materiales. Cada curso conserva sus propios archivos y enlaces.'} Puedes reunir hasta 50 materiales en cada curso.</p>${courseField}${languageField}<div class="source-picker"><b>Archivos del curso</b><small>PDF, Word, PowerPoint, Excel, imágenes, texto y vídeo · puedes seleccionar varios</small><input type="file" id="file" multiple accept="${supportedFiles}"></div><div class="link-add"><input class="field" id="sourceUrl" type="url" placeholder="Pega un enlace web o de YouTube"><button class="secondary" id="addLink">Añadir enlace</button></div><div class="source-summary"><b>Materiales para este curso</b><span id="sourceCount">0/50 materiales</span></div><div class="source-list" id="sourceList"></div><label class="auth-label">Fecha del examen (opcional)<input class="field" type="date" id="examDate" value="${escapeHtml(mode==='add'&&selected?.examDate||'')}"></label><label class="auth-label">Nota objetivo (sobre 10)<input class="field" type="number" id="targetGrade" min="1" max="10" step="0.1" value="${escapeHtml(mode==='add'&&selected?.targetGrade||8)}"></label><small>Al empezar el curso se crea una lista de pasos para esta meta; podrás marcar cada paso al completarlo.</small><div class="prototype-note">${cloudUser?'Tus cursos y archivos se guardarán en tu cuenta para que puedas abrirlos desde otros dispositivos. ':'Los cursos y archivos se guardan en este dispositivo. Entra en tu cuenta para sincronizarlos y acceder desde otros dispositivos.'}</div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" id="saveCourseSources">${mode==='create'?'Crear curso':'Añadir al curso'}</button></div>`);renderSources()}
document.querySelector('#addBtn').onclick=()=>{const courses=loadCourses();if(!courses.length)openMaterialDialog('create');else openMaterialDialog('add',courses[courses.length-1].id)};
document.querySelector('#newCourseBtn').onclick=()=>openMaterialDialog('create');document.querySelector('#continueBtn').onclick=()=>openMaterialDialog('create');
document.querySelector('#courseList').addEventListener('click',e=>{const add=e.target.closest('[data-course-add]'),open=e.target.closest('[data-course-open]');if(add)openMaterialDialog('add',add.dataset.courseAdd);else if(open)showCourseDetails(open.dataset.courseOpen)});
content.addEventListener('change',e=>{if(e.target.id==='courseSelect'){updateSelectedCourseFields();renderSources()}if(e.target.id==='file'){for(const f of [...e.target.files])if(!addSource({type:'file',id:crypto.randomUUID?.()||`${Date.now()}-${Math.random()}`,name:f.name,size:f.size,mime:f.type,fileData:f}))break;e.target.value=''}});
content.addEventListener('click',e=>{if(e.target.id==='addLink'){const input=document.querySelector('#sourceUrl');let url;try{url=new URL(input.value.trim())}catch{toast('Pega un enlace válido que empiece por https://');return}if(!['http:','https:'].includes(url.protocol)){toast('El enlace debe usar http o https.');return}const host=url.hostname.toLowerCase().replace(/^www\./,'');const youtube=['youtube.com','m.youtube.com','youtu.be','youtube-nocookie.com'].some(d=>host===d||host.endsWith(`.${d}`));if(addSource({type:youtube?'youtube':'link',name:youtube?`YouTube · ${url.hostname}${url.pathname}`:url.href,url:url.href}))input.value=''}if(e.target.matches('[data-remove-source]')){pendingSources.splice(Number(e.target.dataset.removeSource),1);renderSources()}});
document.querySelector('#lessonBtn')?.addEventListener('click',()=>openMaterialDialog('create'));
function startLesson(){openModal('Lección guiada · Biología',`<p>Vamos paso a paso. La membrana celular regula qué sustancias entran y salen de la célula.</p><div class="chatbox"><b>✦ Astra</b><div>Imagina la membrana como la puerta de una casa: deja pasar algunas cosas y mantiene otras fuera. El oxígeno, por ejemplo, atraviesa la membrana por difusión, moviéndose desde donde hay más concentración hacia donde hay menos.<br><br><b>Pregunta:</b> si hay más oxígeno fuera de la célula que dentro, ¿hacia dónde se moverá?</div></div><div class="chatinput"><input id="answer" placeholder="Escribe tu respuesta…"><button id="answerBtn">Enviar</button></div>`);setTimeout(()=>{let b=document.querySelector('#answerBtn'),i=document.querySelector('#answer');b.onclick=()=>{let a=i.value.trim();if(!a)return;const box=document.querySelector('.chatbox');box.innerHTML+=`<div style="background:#f1f0e9;border-radius:9px;padding:9px;margin-top:11px"><b>Tú</b><br>${escapeHtml(a)}</div><div><b>✦ Astra</b><br>¡Eso es! El oxígeno se mueve hacia el interior, siguiendo su gradiente de concentración. Has entendido la difusión. ¿Lista para el siguiente concepto?</div>`;i.value='';learned++;document.querySelector('#mastery').textContent=Math.min(100,learned*3)+'%';document.querySelector('#progressBar').style.width=Math.min(100,learned*3)+'%';document.querySelector('#lessonTitle').textContent='Ósmosis: el movimiento del agua';toast('¡Buen trabajo! Progreso actualizado')};i.addEventListener('keydown',e=>{if(e.key==='Enter')b.click()})},0)}
function escapeHtml(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function openCards(course){openModal(`${response(course,'Tarjetas de memoria','Flashcards','Memoria-txartelak')} · ${escapeHtml(course?.name||'Asignatura')}`,`<p>${response(course,`Las tarjetas de «${escapeHtml(course?.name||'esta asignatura')}» se crearán a partir de sus materiales.`,`Flashcards for “${escapeHtml(course?.name||'this subject')}” will be created from its materials.`,`«${escapeHtml(course?.name||'ikasgai')}» ikasgaiaren txartelak haren materialetatik sortuko dira.`)}</p><div class="prototype-note">${response(course,'La generación de tarjetas y el repaso adaptativo necesitan conectar IA.','Flashcard generation and adaptive review need an AI service.','Txartelak sortzeko eta errepaso egokitua egiteko, IA zerbitzu bat konektatu behar da.')}</div><div class="modal-actions"><button class="primary" onclick="closeModal()">${response(course,'Volver a la asignatura','Back to subject','Ikasgaira itzuli')}</button></div>`)}
function openQuiz(course){openModal(`${response(course,'Cuestionario','Quiz','Galdetegia')} · ${escapeHtml(course?.name||'Asignatura')}`,`<p>${response(course,'Pregunta de práctica','Practice question','Praktikatzeko galdera')}</p><div class="chatbox"><b>${response(course,`¿Qué tema de ${escapeHtml(course?.name||'esta asignatura')} quieres practicar primero?`,`Which topic in ${escapeHtml(course?.name||'this subject')} would you like to practise first?`,`Zein gai landu nahi duzu lehenik ${escapeHtml(course?.name||'ikasgai')} ikasgaian?`)}</b><div id="options" style="display:grid;gap:8px;margin-top:14px"><button class="secondary" data-answer="a">${response(course,'El primer tema','The first topic','Lehenengo gaia')}</button><button class="secondary" data-answer="b">${response(course,'El tema que más me cuesta','The topic I find hardest','Gehien kostatzen zaidan gaia')}</button><button class="secondary" data-answer="c">${response(course,'Repaso general','General review','Errepaso orokorra')}</button></div><div id="feedback"></div></div><small class="auth-note">${response(course,'El cuestionario personalizado necesita conectar IA.','Personalised quizzes need an AI service.','Galdetegi pertsonalizatuek IA zerbitzu bat behar dute.')}</small>`);content.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{content.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);document.querySelector('#feedback').innerHTML=`<p>${response(course,`Selección guardada para «${escapeHtml(course?.name||'la asignatura')}». El cuestionario personalizado necesita IA.`,`Selection saved for “${escapeHtml(course?.name||'this subject')}”. Personalised quizzes need AI.`,`«${escapeHtml(course?.name||'ikasgaia')}» ikasgairako hautaketa gorde da. Galdetegi pertsonalizatuak IAk sortu behar ditu.`)}</p>`})}
const checkGoal=document.querySelector('#checkGoal'),checkCards=document.querySelector('#checkCards');if(checkGoal)checkGoal.onclick=e=>{e.currentTarget.classList.toggle('done');if(e.currentTarget.classList.contains('done')){toast('Objetivo completado. ¡Vas genial!');learned++;document.querySelector('#mastery').textContent=Math.min(100,learned*3)+'%'}};if(checkCards)checkCards.onclick=e=>{e.currentTarget.classList.toggle('done');if(e.currentTarget.classList.contains('done'))openCards()};
document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');let p=b.dataset.page;document.querySelector('#crumb').textContent=p;if(p==='Tutor IA')document.querySelector('[data-tool="Tutor IA"]').click();else if(p==='Tarjetas')openCards();else if(p==='Mis asignaturas'){const courses=loadCourses();openModal('Mis asignaturas',courses.length?`<p>Tus cursos y materiales guardados en este navegador.</p><div class="source-list">${courses.map(c=>`<div class="source-row"><span>▤</span><span class="source-name"><b>${escapeHtml(c.name)}</b> · ${c.sources.length}/50 materiales</span></div>`).join('')}</div><div class="modal-actions"><button class="primary" onclick="closeModal();document.querySelector('#addBtn').click()">＋ Añadir materiales</button></div>`:`<p>Aún no tienes cursos. Añade materiales para crear el primero.</p><div class="modal-actions"><button class="primary" onclick="closeModal();document.querySelector('#addBtn').click()">Crear mi primer curso&nbsp; →</button></div>`)}else if(p==='Mi progreso'){const courses=loadCourses();openModal('Mi progreso',`<p>Tu recorrido de estudio en este dispositivo.</p><div class="metrics"><div class="metric"><div><small>Cursos</small><strong>${courses.length}</strong></div></div><div class="metric"><div><small>Materiales</small><strong>${courses.reduce((n,c)=>n+c.sources.length,0)}</strong></div></div><div class="metric"><div><small>Dominio</small><strong>0%</strong></div></div></div><div class="goal"><span class="goal-icon">🔥</span><div><strong>Tu racha empieza hoy</strong><small>Completa una sesión de estudio cada día.</small></div></div>`)}else if(p!=='Inicio')toast(`${p}: tu espacio de estudio está listo`)});
content.addEventListener('click',async e=>{if(e.target.id==='createAnotherCourse'){openMaterialDialog('create');return}if(e.target.dataset.openFile){const [courseId,sourceId]=e.target.dataset.openFile.split('|');openLocalFile(courseId,sourceId);return}if(e.target.id!=='saveCourseSources')return;let courses=loadCourses(),course=null;if(sourceMode==='create'){const name=document.querySelector('#courseName').value.trim();if(!name){toast('Escribe un nombre para el curso.');document.querySelector('#courseName').focus();return}if(!pendingSources.length){toast('Añade al menos un archivo o enlace para crear el curso.');return}const language=document.querySelector('#courseLanguage').value,targetGrade=normalizeTargetGrade(document.querySelector('#targetGrade').value);course={id:crypto.randomUUID?.()||String(Date.now()),name,sources:[],examDate:'',language,targetGrade,studyPlan:buildStudyPlan(targetGrade,language),startedAt:'',createdAt:new Date().toISOString()};courses.push(course)}else{course=courses.find(c=>c.id===document.querySelector('#courseSelect').value);if(!course){toast('Selecciona el curso al que añadir el material.');return}if(course.sources.length+pendingSources.length>50){toast(`«${course.name}» ya tiene ${course.sources.length} materiales; el máximo es 50.`);return}}try{await storeLocalFiles(course.id,pendingSources);if(cloudUser)for(const source of pendingSources)if(source.type==='file')await uploadCloudFile(course.id,source)}catch(error){toast(error.message||'No se pudieron guardar los archivos.');return}const savedSources=pendingSources.map(({fileData,...source})=>source);course.sources.push(...savedSources);const oldTargetGrade=normalizeTargetGrade(course.targetGrade);course.examDate=document.querySelector('#examDate').value||course.examDate;course.language=document.querySelector('#courseLanguage').value;course.targetGrade=normalizeTargetGrade(document.querySelector('#targetGrade').value||course.targetGrade);syncStudyPlan(course);if(oldTargetGrade!==course.targetGrade&&course.startedAt)toast(response(course,'La meta cambió; se ha actualizado el plan del curso desde cero.','Your target changed; the course plan has been reset.','Helburua aldatu da; ikastaroaren plana hasieratik eguneratu da.'));localStorage.setItem('astra-demo-courses',JSON.stringify(courses));try{await persistCloudCourses(courses)}catch(error){toast(`Guardado en este dispositivo; no se pudo sincronizar: ${error.message}`);return}const count=pendingSources.length;pendingSources=[];closeModal();renderCourseList();toast(count?`${sourceMode==='create'?'Curso creado':'Materiales añadidos'} · ${count} en «${course.name}».`:`Preferencias de «${course.name}» actualizadas.`)});
function renderCourseList(){const list=document.querySelector('#courseList'),courses=loadCourses();document.querySelector('#coursesHeading').textContent=courses.length?`Mis cursos · ${courses.length}`:'Mis cursos';if(!courses.length){list.innerHTML=`<div class="course-empty"><div class="empty-icon">＋</div><h3>Aún no tienes cursos</h3><p>Crea un curso para reunir sus apuntes, enlaces y fecha de examen en un solo lugar.</p><button class="primary" id="emptyCreateCourse">Crear mi primer curso</button></div>`;document.querySelector('#emptyCreateCourse').onclick=()=>openMaterialDialog('create');return}const accents=['#d8f36a','#f5d8a8','#d8d2ff','#bfe5dc','#f1c6c3'];list.innerHTML=courses.map((c,i)=>{const planProgress=studyPlanProgress(c),exam=c.examDate?new Date(`${c.examDate}T12:00:00`).toLocaleDateString('es-ES',{day:'numeric',month:'short'}):'Sin fecha de examen';return `<article class="course-card" style="--course-accent:${accents[i%accents.length]}"><div class="course-card-top"><div class="course-badge">${['✦','▤','⚛','◉','✎'][i%5]}</div><span class="course-state">${c.startedAt?'En curso':'Sin empezar'}</span></div><h3>${escapeHtml(c.name)}</h3><p class="course-meta">${c.sources.length} de 50 materiales <span>·</span> ${escapeHtml(courseLanguage(c))} <span>·</span> Objetivo ${c.targetGrade||8}/10 <span>·</span> ${escapeHtml(exam)}</p><div class="course-progress"><div><span>Plan completado</span><b>${planProgress.percent}%</b></div><div class="bar"><i style="width:${planProgress.percent}%"></i></div></div><div class="course-actions"><button class="secondary" data-course-open="${escapeHtml(c.id)}">${c.startedAt?'Continuar':'Empezar curso'}</button><button class="primary" data-course-add="${escapeHtml(c.id)}">＋ Añadir material</button></div></article>`}).join('');document.querySelector('.hero h2').textContent='Sigue avanzando, curso a curso.';document.querySelector('.hero-copy p').textContent='Cada curso tiene su propio material y fecha de examen. Añade apuntes para ampliar un curso o crea uno nuevo.';document.querySelector('#continueBtn').textContent='＋ Crear otro curso';document.querySelector('#continueBtn').onclick=()=>openMaterialDialog('create')}
const courseTools=[['Lección guiada','01','Lección guiada'],['Podcast','02','Podcast del tema'],['Tarjetas','03','Tarjetas de memoria'],['Quiz','04','Cuestionario'],['Texto inteligente','05','Lección de texto inteligente'],['Verdadero o falso','06','Lección de verdadero / falso'],['Repetición','07','Repetición'],['Lagunas de conocimiento','08','Lagunas de conocimiento'],['Examen oral','09','Examen oral simulado'],['Examen escrito','10','Examen escrito simulado'],['Tutor IA','✧','Pregunta al tutor'],['Escanear problema','📷','Resolver desde una foto'],['Ejercicio','✎','Ejercicio guiado'],['Calendario de estudio','▦','Fecha y sesiones'],['Learning apps','⚛','Modelo interactivo'],['Juegos mentales','♟','Reto de lógica'],['Compartir curso','♧','Estudiar con la clase']];
