function winAnsiHex(value){const special={'€':128,'‚':130,'ƒ':131,'„':132,'…':133,'†':134,'‡':135,'ˆ':136,'‰':137,'Š':138,'‹':139,'Œ':140,'Ž':142,'‘':145,'’':146,'“':147,'”':148,'•':149,'–':150,'—':151,'˜':152,'™':153,'š':154,'›':155,'œ':156,'ž':158,'Ÿ':159};return Array.from(value).map(ch=>{let n=special[ch]??ch.codePointAt(0);if(n>255)n=63;return n.toString(16).padStart(2,'0')}).join('').toUpperCase()}
function buildExamPdf(course,difficulty,minutes){const sourceNames=[...new Set((course.sources||[]).map(s=>s.name.replace(/\.[^/.]+$/,'').replace(/[_-]+/g,' ').trim()).filter(Boolean))];const templates={Básica:['Define con tus palabras las ideas principales de «{source}».','Resume la información más importante de «{source}».','Enumera y explica dos conceptos clave de «{source}».','Da un ejemplo sencillo relacionado con «{source}».'],Intermedia:['Relaciona dos conceptos importantes de «{source}» y explica cómo se conectan.','Aplica una idea de «{source}» a una situación práctica.','Compara los conceptos principales de «{source}» e indica una diferencia relevante.','Explica una causa y una consecuencia relacionadas con «{source}».'],Avanzada:['Analiza críticamente las ideas de «{source}» y justifica tu interpretación.','Integra varios conceptos de «{source}» en una explicación fundamentada.','Evalúa cómo aplicarías los principios de «{source}» a un caso nuevo.','Formula una conclusión razonada a partir de la información de «{source}».']};const otherTemplates={en:{Básica:['Define the main ideas in “{source}” in your own words.','Summarise the most important information in “{source}”.','List and explain two key concepts from “{source}”.','Give a simple example related to “{source}”.'],Intermedia:['Connect two important concepts from “{source}” and explain their relationship.','Apply an idea from “{source}” to a practical situation.','Compare the main concepts in “{source}” and describe one important difference.','Explain a cause and an effect related to “{source}”.'],Avanzada:['Critically analyse the ideas in “{source}” and justify your interpretation.','Combine several concepts from “{source}” in a well-supported explanation.','Evaluate how you would apply the principles in “{source}” to a new case.','Draw a reasoned conclusion from the information in “{source}”.']},eu:{Básica:['Azaldu zure hitzekin «{source}» ataleko ideia nagusiak.','Laburbildu «{source}» ataleko informaziorik garrantzitsuena.','Zerrendatu eta azaldu «{source}» ataleko bi funtsezko kontzeptu.','Eman «{source}» gaiarekin lotutako adibide erraz bat.'],Intermedia:['Lotu «{source}» ataleko bi kontzeptu garrantzitsu eta azaldu haien arteko harremana.','Aplikatu «{source}» ataleko ideia bat egoera praktiko batean.','Konparatu «{source}» ataleko kontzeptu nagusiak eta adierazi alde garrantzitsu bat.','Azaldu «{source}» gaiarekin lotutako kausa eta ondorio bat.'],Avanzada:['Aztertu kritikoki «{source}» ataleko ideiak eta justifikatu zure interpretazioa.','Integratu «{source}» ataleko hainbat kontzeptu azalpen arrazoitu batean.','Ebaluatu nola aplikatuko zenituzkeen «{source}» ataleko printzipioak kasu berri batean.','Atera ondorio arrazoitu bat «{source}» ataleko informaziotik.']}};const questionTemplates=(otherTemplates[course.language]||templates)[difficulty];;const questions=Array.from({length:8},(_,i)=>{const source=sourceNames.length?sourceNames[i%sourceNames.length]:course.name;return questionTemplates[i%4].replaceAll('{source}',source)});const labels={examTitle:{es:'SIMULACRO ESCRITO',en:'WRITTEN MOCK EXAM',eu:'IDATZIZKO AZTERKETA'},difficulty:{es:'Dificultad',en:'Difficulty',eu:'Zailtasuna'},time:{es:'Tiempo disponible',en:'Time available',eu:'Eskuragarri dagoen denbora'},date:{es:'Fecha',en:'Date',eu:'Data'},instructions:{es:'Instrucciones: responde con claridad y justifica tus respuestas.',en:'Instructions: answer clearly and justify your answers.',eu:'Argibideak: erantzun argi eta azaldu zure erantzunen arrazoiak.'},answerSheet:{es:'Escribe las respuestas en los espacios señalados. Revisa al final.',en:'Write your answers in the spaces provided. Review them at the end.',eu:'Idatzi erantzunak adierazitako tokietan. Amaieran berrikusi.'},question:{es:'PREGUNTA',en:'QUESTION',eu:'GALDERA'},page:{es:'Página',en:'Page',eu:'Orria'},locale:{es:'es-ES',en:'en-GB',eu:'eu-ES'}};const l=labels[course.language]||labels.es;const difficultyLevels={es:{Básica:'Básica',Intermedia:'Intermedia',Avanzada:'Avanzada'},en:{Básica:'Basic',Intermedia:'Intermediate',Avanzada:'Advanced'},eu:{Básica:'Oinarrizkoa',Intermedia:'Ertaina',Avanzada:'Aurreratua'}}[course.language]||{Básica:'Básica',Intermedia:'Intermedia',Avanzada:'Avanzada'};const level=difficultyLevels[difficulty]||difficulty;const pages=[];const wrap=(text,limit=82)=>{const words=text.split(/\s+/),lines=[];let line='';for(const word of words){if(line&&`${line} ${word}`.length>limit){lines.push(line);line=word}else line=line?`${line} ${word}`:word}if(line)lines.push(line);return lines};for(let page=0;page<4;page++){const commands=[];const txt=(text,x,y,size=11,font='F1')=>commands.push(`BT /${font} ${size} Tf ${x} ${y} Td <${winAnsiHex(text)}> Tj ET`);const rule=y=>commands.push(`0.6 w 52 ${y} m 543 ${y} l S`);commands.push('q 0.95 0.79 0.30 rg 0 752 595 90 re f Q');txt('ASTRA ESTUDIO',52,818,10,'F2');txt(l.examTitle,52,790,21,'F2');txt(course.name,52,768,12,'F1');if(page===0){txt(`${l.difficulty}: ${level}`,52,724,11,'F2');txt(`${l.time}: ${minutes} min`,250,724,11,'F2');txt(`${l.date}: ${new Date().toLocaleDateString(l.locale)}`,52,701,10);txt(l.instructions,52,678,10);txt(l.answerSheet,52,662,10)}const first=page*2;for(let j=0;j<2;j++){const q=first+j;const y=(page===0?632:718)-j*286;txt(`${l.question} ${String(q+1).padStart(2,'0')}`,52,y,10,'F2');const lines=wrap(questions[q]);lines.forEach((line,k)=>txt(line,52,y-21-k*16,11));const answerStart=y-21-lines.length*16-13;for(let k=0;k<6;k++)rule(answerStart-k*24)}txt(`${course.name}  ·  ${level}  ·  ${minutes} min`,52,28,8);txt(`${l.page} ${page+1} / 4`,480,28,8);pages.push(commands.join('\n'))}const objects=[];objects.push('<< /Type /Catalog /Pages 2 0 R >>');objects.push('');objects.push('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>');objects.push('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>');const pageIds=[];pages.forEach(stream=>{const pageId=objects.length+1,contentId=pageId+1;pageIds.push(pageId);objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents ${contentId} 0 R >>`);objects.push(`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`)});objects[1]=`<< /Type /Pages /Kids [${pageIds.map(id=>`${id} 0 R`).join(' ')}] /Count ${pages.length} >>`;let pdf='%PDF-1.4\n',offsets=[0];objects.forEach((obj,i)=>{offsets.push(pdf.length);pdf+=`${i+1} 0 obj\n${obj}\nendobj\n`});const xref=pdf.length;pdf+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n`;for(let i=1;i<offsets.length;i++)pdf+=`${String(offsets[i]).padStart(10,'0')} 00000 n \n`;pdf+=`trailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;return new Blob([pdf],{type:'application/pdf'})}
function generateExamPdf(course,difficulty,minutes){const blob=buildExamPdf(course,difficulty,minutes),url=URL.createObjectURL(blob),slug=course.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'')||'asignatura',filename=`Simulacro-${slug}-${difficulty.toLowerCase()}-${minutes}min.pdf`,link=document.createElement('a');link.href=url;link.download=filename;link.click();featureModal(response(course,'Tu examen está listo','Your exam is ready','Azterketa prest dago'),`<p>${response(course,`Se ha generado el simulacro de <b>${escapeHtml(course.name)}</b>.`,`The mock exam for <b>${escapeHtml(course.name)}</b> is ready.`,`<b>${escapeHtml(course.name)}</b> ikasgairako simulazioa sortu da.`)}</p><div class="goal"><span class="goal-icon">📄</span><div><strong>${difficulty} · ${minutes} ${response(course,'minutos','minutes','minutu')}</strong><small>${response(course,'PDF de 4 páginas con 8 preguntas y espacio para responder','4-page PDF with 8 questions and answer space','4 orrialdeko PDFa, 8 galdera eta erantzuteko tartearekin')}</small></div></div><div class="modal-actions"><a class="primary download-link" href="${url}" download="${escapeHtml(filename)}">${response(course,'Descargar el PDF otra vez','Download the PDF again','Deskargatu PDFa berriro')}</a><button class="secondary" onclick="closeModal()">${response(course,'Volver a la asignatura','Back to subject','Ikasgaira itzuli')}</button></div><small class="auth-note">${response(course,'Las preguntas se orientan con los nombres de los materiales; el contenido de los archivos todavía no se analiza con IA.','Questions are based on material titles; file contents are not analysed by AI yet.','Galderak materialen izenetan oinarritzen dira; fitxategien edukia ez du IAk aztertzen oraindik.')}</small>`);setTimeout(()=>URL.revokeObjectURL(url),10*60*1000)}
